855	  /**
856	   * Drain queues, spawning invocations up to each agent's max_concurrent limit.
857	   * AC: @agent-dispatch-engine ac-3, ac-17
858	   */
859	  private async _drainQueues(agents: LoadedAgent[]): Promise<void> {
860	    // Prevent new invocation starts during/after shutdown.
861	    if (!this.running) return;
862	
863	    // AC: @agent-dispatch-engine ac-17 - Load current tasks once for staleness + readiness checks
864	    let currentTasks: LoadedTask[] | undefined;
865	    let currentTaskStates: Map<string, TaskStatus> | undefined;
866	    try {
867	      const ctx = await initContext(this.projectDir);
868	      currentTasks = await loadAllTasks(ctx);
869	      currentTaskStates = new Map(
870	        currentTasks.map((t) => [t._ulid, t.status as TaskStatus]),
871	      );
872	    } catch {
873	      // If we can't load tasks, skip staleness checks (best effort)
874	    }
875	
876	    for (const agent of agents) {
877	      const maxConcurrent = agent.concurrency?.max_concurrent ?? 1;
878	      const active = this.activeCount.get(agent.id) ?? 0;
879	      const queue = this.queues.get(agent.id) ?? [];
880	
881	      // AC: @agent-dispatch-engine ac-17 - Discard stale entries before spawning.
882	      // Only discard when we have positive evidence the task moved: either the task
883	      // exists on disk with a different status, or the task was previously tracked
884	      // (in prevTaskStates) but is no longer found (deleted).
885	      if (currentTaskStates) {
886	        const before = queue.length;
887	        for (let i = queue.length - 1; i >= 0; i--) {
888	          const entry = queue[i];
889	          const currentStatus = currentTaskStates.get(entry.change.taskId);
890	          const expectedEvent = STATUS_TO_EVENT[entry.change.toStatus];
891	          if (!expectedEvent) continue; // No event mapping — skip check
892	          if (currentStatus === undefined) {
893	            // Task not on disk — only discard if we previously knew about it
894	            // (it was deleted). Tasks from pure handleStateChange events without
895	            // on-disk presence should still be processed.
896	            if (this.prevTaskStates.has(entry.change.taskId)) {
897	              queue.splice(i, 1);
898	            }
899	          } else {
900	            const currentEvent = STATUS_TO_EVENT[currentStatus];
901	            if (currentEvent !== expectedEvent) {
902	              queue.splice(i, 1);
903	            }
904	          }
905	        }
906	        if (before > queue.length) {
907	          console.log(
908	            `[dispatch] Discarded ${before - queue.length} stale queue entries for agent "${agent.id}"`,
909	          );
910	        }
911	      }
912	
913	      // AC: @trait-task-readiness ac-deps, ac-not-blocked — discard entries
914	      // where deps are no longer met or task became blocked since enqueue
915	      if (currentTasks) {
916	        for (let i = queue.length - 1; i >= 0; i--) {
917	          const entry = queue[i];
918	          const eventType = STATUS_TO_EVENT[entry.change.toStatus];
919	          if (eventType !== "task.ready" && eventType !== "task.needs_work") continue;
